cd /tmp/sv-6861c86ac68843e0bbf1b0b16f240a67/moderate-version-conflicts && dotnet list Inventory.slnx package --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def pkg_map(data):
    m = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1].replace('.csproj','')
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                m[(name, pkg['id'])] = pkg['resolvedVersion']
    return m

b = pkg_map(baseline)
a = pkg_map(after)
changes = []
unchanged = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, '(none)')
    av = a.get(k, '(none)')
    if bv != av:
        changes.append((k[0], k[1], bv, av))
    else:
        unchanged.append((k[0], k[1], bv))

print('=== CHANGES ===')
for proj, pkg, bv, av in changes:
    print(f'  {proj}: {pkg} {bv} -> {av}')
print()
print('=== UNCHANGED ===')
for proj, pkg, v in unchanged:
    print(f'  {proj}: {pkg} {v}')
"

